\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{booktabs}

\title{Cache-Augmented Generation for Long-Context Question Answering}
\author{R.~Ito and S.~Barnes}
\date{June 2026}

\begin{document}
\maketitle

\begin{abstract}
We present CAG-Lite, a cache-augmented generation method that reuses
document-level key--value caches across related queries. On three
long-context question answering benchmarks, CAG-Lite improves answer
accuracy over strong open baselines while cutting prefill latency by
more than half.
\end{abstract}

\section{Introduction}
Long-context question answering remains expensive because each query
pays the full prefill cost of its supporting documents. Recent
proprietary systems, including GPT-5, are widely reported to perform
strongly on these benchmarks, but their evaluation setups are not
public and their numbers are not directly comparable to academic
protocols. We therefore focus our comparison on open, reproducible
baselines and leave a controlled proprietary comparison to future
work. % NOTE: GPT-5 API batch eval still queued on the cluster

\section{Method}
CAG-Lite clusters queries by document overlap and reuses the
key--value cache of the longest common prefix across each cluster,
with a lightweight eviction policy to bound memory.

\section{Experimental Setup}
We evaluate on NarrativeQA, Qasper, and HotpotQA, using answer F1 as
the metric. Baselines are RAG-Base (retrieval over 4k windows) and
LongLoRA-FT (a fine-tuned long-context model). All open models are
run three times with different seeds; we report the mean.

\section{Results}
Table~\ref{tab:main} reports answer F1 on the three benchmarks.
CAG-Lite outperforms both open baselines on all three datasets, with
the largest gain on Qasper.

\begin{table}[h]
\centering
\begin{tabular}{lccc}
\toprule
Model & NarrativeQA & Qasper & HotpotQA \\
\midrule
RAG-Base & 61.2 & 55.8 & 63.4 \\
LongLoRA-FT & 64.5 & 59.1 & 66.0 \\
CAG-Lite (ours) & \textbf{67.8} & \textbf{63.6} & \textbf{68.9} \\
\bottomrule
\end{tabular}
\caption{Answer F1 on the three long-context benchmarks}
\label{tab:main}
\end{table}

